#!/usr/bin/env bash
set -euo pipefail
APP_DIR="${APP_DIR:-/home/juanma/projects/kodentra-commander}"
TMP_DIR="$(mktemp -d)"
cleanup(){ rm -rf "$TMP_DIR"; }
trap cleanup EXIT
mkdir -p "$APP_DIR"
cat > "$TMP_DIR/kodentra.zip.b64" <<'PAYLOAD'
[... ELLIPSIZATION ...]
PAYLOAD
base64 -d "$TMP_DIR/kodentra.zip.b64" > "$TMP_DIR/kodentra.zip"
echo "5b5bfb59986ea5ac3a82880c2087b6bd55cc6da4ac691f212c3bd17b1b563331  $TMP_DIR/kodentra.zip" | sha256sum -c -
unzip -q "$TMP_DIR/kodentra.zip" -d "$TMP_DIR/unpack"
rm -rf "$APP_DIR.new"
mv "$TMP_DIR/unpack/kodentra-commander" "$APP_DIR.new"
if [[ -d "$APP_DIR" && -n "$(find "$APP_DIR" -mindepth 1 -maxdepth 1 -print -quit 2>/dev/null)" ]]; then
  backup="${APP_DIR}.backup.$(date +%Y%m%d%H%M%S)"
  mv "$APP_DIR" "$backup"
  echo "[installer] preserved previous tree at $backup"
else
  rm -rf "$APP_DIR"
fi
mv "$APP_DIR.new" "$APP_DIR"
chown -R juanma:juanma "$APP_DIR" 2>/dev/null || true
if [[ "${KODENTRA_EXTRACT_ONLY:-0}" == "1" ]]; then
  echo "[installer] extracted to $APP_DIR; bootstrap skipped"
  exit 0
fi
exec "$APP_DIR/scripts/bootstrap-vps.sh"
